/* Scenic interactions: bounded to home lower screens, roots, about. */
(()=>{
const oldHome=home,oldBind=bindCineInteractions;
const img=(src,alt,cls='')=>`<img class="${cls}" src="assets/${src}" alt="${alt}" draggable="false">`;
const button=(s)=>`<button type="button" class="ex-close" aria-label="关闭细节">返回全景 ↗</button>`;
const notes=[['果皮的颜色','同一张照片里的青绿与橙红，是外观观察的起点。颜色不能替代内部品质检测。'],['看见遮挡','果蒂、枝条与重叠会影响观察。采集时应尽量让目标完整、清晰入镜。']];
const dialog=`<dialog class="ex-dialog"><button class="ex-close" aria-label="关闭">关闭 ×</button><div class="ex-dialog-body"></div></dialog>`;
home=function(){let html=oldHome();let cut=html.indexOf('<section class="cine-scene"');return html.slice(0,cut)+`<section class="ex-orchard ex-scene" id="collection"><div class="ex-mountain ex-depth">${img('taihang-real.jpg','太行山实景')}</div><div class="ex-orchard-head"><span class="ex-kicker">01 / 走近一枚果实</span><h2>山很远。<br>果实，就在眼前。</h2><p>移动视线，点亮一个观察点。</p></div><div class="ex-specimen ex-depth">${img('persimmon.webp','用于观察颜色与遮挡的柿果展示照片')}<button class="ex-hotspot" data-observe="0" style="left:34%;top:55%"><i></i><span>01 看颜色</span></button><button class="ex-hotspot" data-observe="1" style="left:76%;top:48%"><i></i><span>02 看遮挡</span></button></div><div class="ex-observe-panel" hidden>${button()}<span class="ex-kicker">局部观察 / 展示摄影</span><h3></h3><p></p><div class="ex-detail-image" tabindex="0" aria-label="按住拖动查看局部照片">${img('persimmon.webp','柿果局部')}</div><small>按住拖动查看 · Esc 返回</small></div><div class="ex-scene-foot">真实摄影 × 交互观察 <a href="#roots">沿渠走近太行 ↗</a></div></section><section class="ex-season ex-scene"><div class="ex-season-head"><span class="ex-kicker">02 / 把秋色，留在手心</span><h2>成熟，<br>有自己的颜色。</h2><p>拖动色谱，细看四种外观阶段。</p></div><div class="ex-fruit-portrait ex-depth">${img('persimmon.webp','柿子外观颜色模拟')}<span class="ex-crosshair"></span><small>同一照片的局部调色示意</small></div><div class="ex-spectrum"><label for="ex-ripeness">外观色谱 <span id="ex-grade">着色期</span></label><input id="ex-ripeness" type="range" min="0" max="3" step=".01" value="2"><div class="ex-ticks"><span>未熟</span><span>转色期</span><span>着色期</span><span>完熟</span></div><p id="ex-stage-note" aria-live="polite"></p><a class="ex-action" href="#recognize">带上你的果实照片 →</a><small>颜色模拟不是实际成熟过程，也不是检测结果。</small></div></section>`};
roots=function(){return `<section class="ex-canal ex-scene"><div class="ex-canal-photo ex-depth">${img('hongqi-real.jpg','红旗渠青年洞实景')}</div><div class="ex-canal-title"><span class="ex-kicker">山渠与果园 / WATER & LAND</span><h1>向山而行。<br><em>循渠而近。</em></h1><p>一段人工渠道，一面真实山体。<br>移动视线，打开画面里的细节。</p></div><svg class="ex-guide" viewBox="0 0 1000 650" preserveAspectRatio="none" aria-hidden="true"><path d="M180 610 Q470 520 580 400 T850 220"/></svg><button class="ex-hotspot" data-canal="0" style="left:55%;top:65%"><i></i><span>近看渠道</span></button><button class="ex-hotspot" data-canal="1" style="left:78%;top:38%"><i></i><span>近看岩壁</span></button><div class="ex-scene-foot">叙事引导线 · 非真实地图路线 <span>青年洞 / WINDMEMORIES · CC BY-SA 4.0</span></div></section><section class="ex-field ex-scene"><div><span class="ex-kicker">从山渠，到果实</span><h2>换一个角度，<br>问题就被看见。</h2><p>在采集之前，先理解照片。<br>选择一个观察问题，按住对照按钮看标记。</p><div class="ex-tabs" role="group" aria-label="采集观察主题">${['颜色','遮挡','距离'].map((v,i)=>`<button data-field="${i}" aria-pressed="${i===0}">${v}</button>`).join('')}</div><h3 id="ex-field-title"></h3><p id="ex-field-note"></p><button class="ex-action" id="ex-compare" aria-pressed="false">按住查看观察位置 / 点击切换</button><small>展示照片上的观察指引，非模型检测或团队采集记录。</small></div><div class="ex-field-image">${img('persimmon.webp','柿果展示摄影')}<div class="ex-field-mark"><span>观察区域</span></div></div>${cineSources()}</section>${dialog}`};
const files=[
['分级依据','四级分级，先看清标准。','根据《太行智农项目计划书》3.5 节：未熟为青绿，转色期为黄橙，着色期为橙红，完熟为深红。文档记录四类平均色相分别为 62.7°、53.2°、35.6°、29.5°，这些是该批数据的统计量，不是通用品种阈值。网络展示照片不作为模型标准样本。',null,'来源：用户提供计划书 3.5 节 / 外观分级不替代糖度与脱涩检测。'],
['数据与采集','443 张图像，是一次积累的起点。','计划书记录：成熟度分类集 443 张，训练 353 张、验证 90 张；果实检测集 108 张，训练 92 张、验证 16 张。采用分层划分并做重复校验。文档记载了产区调研与 105 张果园照片采集；这些原始果园样本尚未在本站公开展示；网上照片不替代团队记录。',null,'来源：计划书 1.7、2.4、3.14 节；独立测试集尚未建立。'],
['实验与边界','有效的进步，也留下待解的问题。','计划书验证集记录：分类 top-1 为 88.89%（80/90），检测 mAP@0.5 为 90.87%；二者是不同任务的指标，不能视为整套系统准确率。逐类召回率中，转色期为 73.68%，是当前薄弱环节。文档还记录了整树小目标漏检问题。下图取自项目计划书的实验记录。','project-recall.webp','来源：计划书 3.17—3.19 节；非独立测试集结果，非生产效果承诺。'],
['技术与进度','先定位，再逐果分级。','计划书采用 YOLO11n 检测与 YOLO11n-cls 分类的两级流水线，手机拍照和固定摄像头为两种采集方式，两层模型合计约 8.27 MB。文档记录了后端与本地推理链路的开发；当前这个展示网站尚未接入该服务。图为计划书中的训练参数适配对比：着色期召回率由 64% 提至 88%。','project-adaptation.webp','来源：计划书 3.3、3.15、3.19、3.23 节；文档记载与当前网页接入状态分开呈现。']];
about=function(){return `<section class="ex-project ex-scene"><div class="ex-project-heading"><span class="ex-kicker">太行果眸 / 项目与验证</span><h1>一张照片，<br>如何走向一个答案？</h1><p>亲手走过三个环节。每一步，都说清楚边界。</p></div><div class="ex-process"><div class="ex-process-photo">${img('persimmon.webp','流程演示的输入照片')}<span>展示照片 · 流程演示</span></div><div class="ex-process-line"></div><div class="ex-process-controls">${['输入照片','模型处理','查看结果'].map((x,i)=>`<button data-process="${i}" aria-pressed="${i===0}"><b>0${i+1}</b>${x}<span>↗</span></button>`).join('')}</div><div class="ex-process-detail" aria-live="polite"><span class="ex-kicker" id="ex-process-status"></span><h3 id="ex-process-title"></h3><p id="ex-process-copy"></p><a href="#recognize">打开识别台 ↗</a></div></div><small>当前演示不运行模型，不生成虚构等级或置信度。</small></section><section class="ex-archive ex-scene"><div class="ex-archive-head"><span class="ex-kicker">OPEN THE FIELD NOTES</span><h2>把依据，<br>摊开来看。</h2><p>点开一份档案，查看当前材料与待完成事项。</p></div><div class="ex-files">${files.map((f,i)=>`<button class="ex-file" data-file="${i}" style="--i:${i}"><span>太行果眸 / 工作档案</span>${f[3]?img(f[3],f[0]):`<div class="ex-file-code">${i===0?'04<br>LEVELS':i===1?'443<br>IMAGES':'INPUT<br>→ MODEL<br>→ RESULT'}</div>`}<b>0${i+1} / ${f[0]}</b><small>${i===0?'计划书分级依据':i===1?'计划书记载':'计划书实验记录'} ↗</small></button>`).join('')}</div>${cineSources()}</section>${dialog}`};
bindCineInteractions=function(){
 if(route==='recognize'){oldBind();blink();return;}
 const root=document.getElementById('app'),reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
 root.querySelectorAll('.ex-scene').forEach(s=>{if(reduce||!matchMedia('(pointer:fine)').matches)return;s.onpointermove=e=>{let r=s.getBoundingClientRect();s.style.setProperty('--mx',((e.clientX-r.left)/r.width-.5).toFixed(3));s.style.setProperty('--my',((e.clientY-r.top)/r.height-.5).toFixed(3));};s.onpointerleave=()=>{s.style.setProperty('--mx',0);s.style.setProperty('--my',0)}});
 const dlg=root.querySelector('dialog');function open(content){dlg.querySelector('.ex-dialog-body').innerHTML=content;dlg.showModal()}if(dlg){dlg.querySelector('.ex-close').onclick=()=>dlg.close();dlg.onclick=e=>{if(e.target===dlg)dlg.close()}}
 if(route==='home'){
 let panel=root.querySelector('.ex-observe-panel'),trigger=null;const close=()=>{panel.hidden=true;root.querySelector('.ex-orchard').classList.remove('observing');trigger?.focus()};root.querySelectorAll('[data-observe]').forEach(b=>b.onclick=()=>{trigger=b;let i=+b.dataset.observe;panel.hidden=false;panel.querySelector('h3').textContent=notes[i][0];panel.querySelector('p').textContent=notes[i][1];panel.querySelector('img').style.objectPosition=i?'78% 55%':'33% 55%';root.querySelector('.ex-orchard').classList.add('observing');panel.querySelector('button').focus()});panel.querySelector('button').onclick=close;panel.onkeydown=e=>{if(e.key==='Escape')close()};let detail=panel.querySelector('.ex-detail-image'),drag=null;detail.onpointerdown=e=>{drag={x:e.clientX};detail.setPointerCapture(e.pointerId)};detail.onpointermove=e=>{if(drag)detail.querySelector('img').style.objectPosition=`${Math.max(0,Math.min(100,50+(e.clientX-drag.x)/3))}% 55%`};detail.onpointerup=detail.onpointercancel=()=>drag=null;
 let range=root.querySelector('#ex-ripeness'),photo=root.querySelector('.ex-fruit-portrait img');range.oninput=()=>{let n=+range.value,k=Math.round(n);photo.style.filter=`hue-rotate(${48-n*20}deg) saturate(${.55+n*.1})`;root.querySelector('#ex-grade').textContent=['未熟','转色期','着色期','完熟'][k];root.querySelector('#ex-stage-note').textContent=['青绿底色，是外观观察的一个起点。','黄绿与橙色交织，留意着色分布。','橙色逐渐铺开，表面仍有细微差异。','充分着色，也不能直接说明糖度与脱涩状态。'][k];range.setAttribute('aria-valuetext',['未熟','转色期','着色期','完熟'][k])};range.onchange=()=>{range.value=Math.round(+range.value);range.oninput()};range.oninput();
 }
 if(route==='roots'){
 root.querySelectorAll('[data-canal]').forEach(b=>b.onclick=()=>{let i=+b.dataset.canal;open(`<span class="ex-kicker">同图局部 / ${i?'岩壁':'渠道'}</span><h2>${i?'山体的纹理。':'沿山延伸的水路。'}</h2><div class="ex-canal-crop ${i?'rock':''}">${img('hongqi-real.jpg','红旗渠青年洞照片局部')}</div><p>从实景局部观察渠道与山体的关系。此处为同一照片裁切，非新增现场采集材料。</p>`)});
 const data=[['同图里的不同底色','从青绿到橙红，颜色只是外观线索。均匀光线有助于比较。',[20,41,34,27]],['让目标少一点遮挡','果蒂与相邻果实的关系，需要在采集时留意。',[69,40,24,28]],['为目标留下足够像素','照片可放大，但不能补回原本没有拍清的纹理。',[39,40,16,28]]];let mark=root.querySelector('.ex-field-mark'),compare=root.querySelector('#ex-compare');const toggle=v=>{mark.classList.toggle('visible',v);compare.setAttribute('aria-pressed',v)};root.querySelectorAll('[data-field]').forEach(b=>b.onclick=()=>{let d=data[+b.dataset.field];root.querySelectorAll('[data-field]').forEach(x=>x.setAttribute('aria-pressed',x===b));root.querySelector('#ex-field-title').textContent=d[0];root.querySelector('#ex-field-note').textContent=d[1];['left','top','width','height'].forEach((x,i)=>mark.style[x]=d[2][i]+'%');toggle(false)});root.querySelector('[data-field]').click();compare.onpointerdown=()=>toggle(true);compare.onpointerup=()=>setTimeout(()=>toggle(false),700);compare.onpointercancel=()=>toggle(false);compare.onclick=e=>{if(e.detail===0)toggle(!mark.classList.contains('visible'))};
 }
 if(route==='about'){
 let ds=[['当前网页 / 本地预览','让照片成为起点。','选择 JPG、PNG 或 WebP，保留原色查看、缩放与平移。当前照片只在浏览器中预览。'],['项目已有技术方案 / 当前网页待接入','模型，要用真实验证说话。','计划书采用两级处理：YOLO11n 定位果实，YOLO11n-cls 逐果分级。文档记载了本地服务的开发；当前展示网页尚未连接该服务。'],['示例可体验 / 真实结果待接入','每个结果，都应对应一个目标。','现有工作台支持人工预设示例与目标联动。真实等级、置信度和失败原因须来自后端。']];root.querySelectorAll('[data-process]').forEach(b=>b.onclick=()=>{let i=+b.dataset.process;root.querySelectorAll('[data-process]').forEach(x=>x.setAttribute('aria-pressed',x===b));['status','title','copy'].forEach((x,k)=>root.querySelector('#ex-process-'+x).textContent=ds[i][k]);root.querySelector('.ex-process').style.setProperty('--step',i)});root.querySelector('[data-process]').click();root.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>{let f=files[+b.dataset.file];open(`<span class="ex-kicker">工作档案 / ${f[0]}</span><h2>${f[1]}</h2>${f[3]?img(f[3],f[0]):''}<p>${f[2]}</p><small>${f[4]}</small>`)});
 }
};
function blink(){document.querySelectorAll('.ow-robot').forEach(b=>{if(b.querySelector('.ex-eye'))return;for(let i=0;i<2;i++){let eye=document.createElement('span');eye.className='ex-eye ex-eye-'+i;eye.setAttribute('aria-hidden','true');b.append(eye)}})}
})();
